You are implementing Task 3: POST /api/persona route for the CLARA backend.

## Project Context

CLARA backend at `/home/advel/workplace/agora/backend/`. Tasks 1 and 2 complete:
- Fastify app running with health check (`src/index.ts`)
- Services: `claudeClient` (Anthropic singleton), `webSearchSource` (PolicySource impl)
- Types defined in `src/types.ts`: `ProfileAnswers`, `Message`, `NoteGroup`, `PolicyResult`
- tsconfig: TypeScript 6, module Node16, CommonJS, strict

The claudeClient has a startup guard — it throws if `ANTHROPIC_API_KEY` is missing. Tests mock it so this doesn't matter during test runs.

**Important:** Test files use `.js` extensions in mock paths (e.g. `'../../src/routes/persona.js'`). This is intentional — Vitest resolves both. Keep mock paths exactly as shown.

## Task Description

**Files:**
- Create: `backend/src/routes/persona.ts`
- Create: `backend/tests/routes/persona.test.ts`
- Modify: `backend/src/index.ts`

**Step 1: Write the failing test**

Create `backend/tests/routes/persona.test.ts`:

```typescript
import { describe, it, expect, vi, beforeEach } from 'vitest'
import Fastify from 'fastify'
import { personaRoute } from '../../src/routes/persona.js'

vi.mock('../../src/services/claudeClient.js', () => ({
  claudeClient: {
    messages: { create: vi.fn() },
  },
}))

import { claudeClient } from '../../src/services/claudeClient.js'

describe('POST /api/persona', () => {
  const app = Fastify()
  app.register(personaRoute)

  beforeEach(() => vi.clearAllMocks())

  it('returns a persona string from Claude', async () => {
    vi.mocked(claudeClient.messages.create).mockResolvedValue({
      content: [{ type: 'text', text: 'Maria, Ukrainian refugee, Munich. Concern: housing.' }],
    } as any)

    const res = await app.inject({
      method: 'POST',
      url: '/api/persona',
      payload: {
        name: 'Maria',
        situation: 'refugee',
        city: 'Munich',
        concern: 'housing',
        language: 'Ukrainian',
      },
    })

    expect(res.statusCode).toBe(200)
    expect(JSON.parse(res.body)).toEqual({
      persona: 'Maria, Ukrainian refugee, Munich. Concern: housing.',
    })
  })

  it('returns 400 when required fields are missing', async () => {
    const res = await app.inject({
      method: 'POST',
      url: '/api/persona',
      payload: { name: 'Maria' },
    })
    expect(res.statusCode).toBe(400)
  })
})
```

**Step 2: Run test to verify it fails**

```bash
cd /home/advel/workplace/agora/backend
npm test
```

Expected: FAIL — module not found for persona route

**Step 3: Write `backend/src/routes/persona.ts`**

```typescript
import type { FastifyInstance } from 'fastify'
import { claudeClient } from '../services/claudeClient'
import type { ProfileAnswers } from '../types'

export async function personaRoute(app: FastifyInstance) {
  app.post<{ Body: ProfileAnswers }>('/api/persona', async (request, reply) => {
    const { name, situation, city, concern, language } = request.body

    if (!name || !situation || !city || !concern || !language) {
      return reply.status(400).send({ error: 'All fields required' })
    }

    const response = await claudeClient.messages.create({
      model: 'claude-sonnet-4-6',
      max_tokens: 256,
      messages: [
        {
          role: 'user',
          content: `Write a 2–3 sentence factual persona summary for a person with these details:
Name: ${name}
Situation: ${situation}
City: ${city}
Main concern: ${concern}
Preferred language: ${language}

Be factual and concise. No assumptions beyond what is given. Output only the summary text.`,
        },
      ],
    })

    const text = response.content.find((b) => b.type === 'text')
    const persona = text?.type === 'text' ? text.text : ''

    return { persona }
  })
}
```

**Step 4: Update `backend/src/index.ts` to register the route**

```typescript
import 'dotenv/config'
import Fastify from 'fastify'
import cors from '@fastify/cors'
import { personaRoute } from './routes/persona'

const app = Fastify({ logger: true })

async function start() {
  await app.register(cors, {
    origin: ['http://localhost:5173', 'http://frontend:5173'],
  })

  await app.register(personaRoute)

  app.get('/health', async () => ({ status: 'ok' }))

  const port = Number(process.env.PORT) || 3000
  await app.listen({ port, host: '0.0.0.0' })
}

start().catch(console.error)
```

**Step 5: Run all tests**

```bash
npm test
```

Expected: all PASS (3 from Task 2 + 2 new = 5 total)

**Step 6: Commit**

```bash
cd /home/advel/workplace/agora/backend
git add .
git commit -m "feat: add POST /api/persona route"
```

